        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDate());
        refuseClosed(sheetId, on);
        claim.setAmount(scaled(amount));
        claim.setDate(on);
        claim.setNote(noteOf(note));
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_EDITED", sheetId, user, person, saved);
        return saved;
    }

    /** Move a claim to a new status; a change its status does not allow is refused, as is the user
     *  who opened a claim settling it. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
        Person person = person(sheetId, personId);
        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
        // read below is its latest state.
        Long number = to == ClaimStatus.OPEN ? sheets.nextClaimNumber(sheetId) : null;
        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
        refuseClosed(sheetId, claim.getDate());
        if (!claim.getStatus().canMoveTo(to)) {
            throw new StatusChangeRefusedException(claim.getStatus(), to);
        }
        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new OwnClaimSettleRefusedException(user);
        }
        Long had = claim.getNumber();
        claim.setStatus(to);
        if (to == ClaimStatus.OPEN) {
            claim.setNumber(number);
            claim.setOpenedBy(user);
        } else if (to == ClaimStatus.SETTLED) {
            claim.setSettledDue(figureOf(sheetId, person, claim));
        } else if (to == ClaimStatus.VOID) {
            claim.setNumber(null);
        }
        Claim saved = claims.saveAndFlush(claim);
        String event = switch (to) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
        };
        String line = line(event, sheetId, user, person, saved, had != null ? had : saved.getNumber());
        if (to == ClaimStatus.SETTLED) {
            line += " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE);
        }
        audit.recordOnCommit(line);
        return saved;
    }

    /** The figure a claim shows: the due fixed when it was settled, else the figure its person's
     *  last statement bound it to, else its due at the person's grade rate; null when it has none. */
    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return claim.isStated() ? claim.getStatedDue() : dueOf(sheetId, person, claim);
    }

    /** The due on a claim at the person's grade rate in force on the claim's date: amount times rate
     *  divided by 100, rounded half to even to two decimals; null when no rate applies. */
    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
        BigDecimal amount = claim.getAmount();
        return rates.rateOn(sheetId, person.getGrade(), claim.getDate())
                .map(Rate::getRate)
                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN))
                .orElse(null);
    }

    /** A claim dated inside a closed period cannot be added, edited, opened, settled or voided. */
    private void refuseClosed(String sheetId, LocalDate date) {
        if (periods.closedOn(sheetId, date)) {
            throw new PeriodClosedException("A claim dated " + date + " falls in a closed period");
        }
    }

    private Person person(String sheetId, Long personId) {
        return people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
    }

    private void record(String event, String sheetId, String user, Person person, Claim claim) {
        record(event, sheetId, user, person, claim, claim.getNumber());
    }

    /** One audit line about a claim; a claim with a number carries it at the end. */
    private void record(String event, String sheetId, String user, Person person, Claim claim, Long number) {
        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
    }

    private static String line(String event, String sheetId, String user, Person person, Claim claim, Long number) {
        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
                + (number != null ? " number=" + number : "");
    }

    private static BigDecimal scaled(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.UNNECESSARY);
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }
}
package net.officefloor.hq.app.claim;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.rollup.RollupService;
import java.util.NoSuchElementException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /** A claim as the screen shows it; the amount and the due fixed on settling (null when none
     *  was) are strings with two decimals; openedBy is null for a claim never opened; stated tells
     *  whether a statement bound the claim, statedDue the figure it bound it to (null when none). */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note,
            ClaimStatus status, Long number, String settledDue, String openedBy, boolean stated,
            String statedDue) {
        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : null,
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() != null ? claim.getStatedDue().toPlainString() : null);
        }
    }

    /** A claim's fields: an amount of 0.00 or more with up to two decimals, a date (blank takes
     *  the sheet's today) and a note (may be empty). */
    public record ClaimRequest(
            @NotNull @DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal amount,
            LocalDate date,
            @Size(max = 2000) String note) {
    }

    private final ClaimService service;
    private final RollupService rollups;

    public ClaimController(ClaimService service, RollupService rollups) {
        this.service = service;
        this.rollups = rollups;
    }

    /** The sheet's claims, newest first. */
    @GetMapping("/claims")
    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId) {
        return service.list(sheetId.trim()).stream().map(ClaimView::of).toList();
    }

    /** Add a claim for a person. */
    @PostMapping("/people/{personId}/claims")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView add(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated ClaimRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return ClaimView.of(rollups.track(sheet, by, () -> service.add(sheet, by, personId, request.amount(),
                request.date(), request.note())));
    }

    /** Change a claim's amount, date and note. */
    @PutMapping("/people/{personId}/claims/{id}")
    public ClaimView update(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated ClaimRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return ClaimView.of(rollups.track(sheet, by, () -> service.update(sheet, by, personId, id,
                request.amount(), request.date(), request.note())));
    }

    /** Open a DRAFT claim. */
    @PostMapping("/people/{personId}/claims/{id}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return changeStatus(sheetId, user, personId, id, ClaimStatus.OPEN);
    }

    /** Settle an OPEN claim; the user who opened it cannot. */
    @PostMapping("/people/{personId}/claims/{id}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return changeStatus(sheetId, user, personId, id, ClaimStatus.SETTLED);
    }

    /** Void a DRAFT or OPEN claim. */
    @PostMapping("/people/{personId}/claims/{id}/void")
    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @PathVariable Long id, @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return changeStatus(sheetId, user, personId, id, ClaimStatus.VOID);
    }

    private ClaimView changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return ClaimView.of(rollups.track(sheet, by, () -> service.changeStatus(sheet, by, personId, id, to)));
    }

    /** A status change the claim's status does not allow, or any change to a claim dated in a
     *  closed period, is refused. */
    @ExceptionHandler({StatusChangeRefusedException.class, PeriodClosedException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void refused() {
    }

    /** The user who opened a claim cannot settle it. */
    @ExceptionHandler(OwnClaimSettleRefusedException.class)
    @ResponseStatus(HttpStatus.FORBIDDEN)
    public void ownClaim() {
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }

    /** An amount that is not a number or a date that is not a real yyyy-mm-dd date is refused. */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }
}

